import mujoco, numpy as np, time, itertools

ref_path='model_ref.xml'
mref=mujoco.MjModel.from_xml_path(ref_path)
print('default opt: iter',mref.opt.iterations,'tol',mref.opt.tolerance,'ls_iter',mref.opt.ls_iterations,'dt',mref.opt.timestep,'solver',mref.opt.solver,'jac',mref.opt.jacobian)

def state_for(m, seed):
    d=mujoco.MjData(m)
    d.qpos += np.random.default_rng(seed).normal(0,0.01,size=d.qpos.shape)
    mujoco.mj_forward(m,d)
    n=int(2.0/m.opt.timestep)
    for _ in range(n):
        mujoco.mj_step(m,d)
    fs=mujoco.mjtState.mjSTATE_FULLPHYSICS
    s=np.zeros(mujoco.mj_stateSize(m,fs))
    mujoco.mj_getState(m,d,s,fs)
    return s

def time_for(m, seeds):
    ts=[]
    for seed in seeds:
        t0=time.perf_counter(); state_for(m,seed); ts.append(time.perf_counter()-t0)
    return np.array(ts)

seeds_acc=[0,1,2,3,4,5]
ref_states={s:state_for(mref,s) for s in seeds_acc}
tref=time_for(mref,[10,11,12])
print('ref time mean %.4f'%tref.mean())

configs=[]
for it in [100,50,20,10,5,3,2,1]:
    configs.append((f'iter{it}',dict(iterations=it)))
for tol in [1e-7,1e-6,1e-5,1e-4]:
    configs.append((f'iter10_tol{tol}',dict(iterations=10,tolerance=tol)))
for ls in [50,20,10,5]:
    configs.append((f'ls{ls}',dict(ls_iterations=ls)))
for dt in [0.0025,0.004,0.005]:
    configs.append((f'dt{dt}',dict(timestep=dt)))

for name,kw in configs:
    m=mujoco.MjModel.from_xml_path(ref_path)
    for k,v in kw.items(): setattr(m.opt,k,v)
    maxdiff=0.0
    for s in seeds_acc:
        st=state_for(m,s)
        maxdiff=max(maxdiff,np.max(np.abs(st-ref_states[s])))
    tt=time_for(m,[10,11,12])
    print('%-20s maxdiff %.3e ratio %.3f time %.4f'%(name,maxdiff,tt.mean()/tref.mean(),tt.mean()))
EOF"}

